// El comunicado llega reenviado COMO ADJUNTO: el .eml original conserva remitente, fecha y Message-ID.
// (El formato RAW del nodo IMAP no sirve: entrega el cuerpo sin cabeceras.)
const FORWARD = /^\s*(RV|RE|FW|FWD|ENC|TR)\s*:/i; // asunto de un reenvío
const out = [];
const badForwards = [];
for (const [i, item] of $input.all().entries()) {
  const binary = item.binary || {};
  const key = Object.keys(binary).find((k) => {
    const b = binary[k];
    return (b.mimeType || '').includes('rfc822') || (b.fileName || '').toLowerCase().endsWith('.eml');
  });
  const forwarder = item.json.from?.value?.[0]?.address || '';
  if (!key) {
    // Otros correos del buzón (avisos de Google, etc.) se ignoran; un reenvío sin el .eml es un error de uso.
    if (FORWARD.test(item.json.subject || '')) badForwards.push(`«${item.json.subject}» de ${forwarder}`);
    continue;
  }
  const eml = await this.helpers.getBinaryDataBuffer(i, key);
  out.push({ json: { raw: eml.toString('base64'), forwarder, asunto: item.json.subject } });
}
if (!out.length && badForwards.length) {
  throw new Error(`Se reenvió de forma normal, sin el comunicado adjunto (.eml): ${badForwards.join('; ')}. En Outlook usa «Reenviar como datos adjuntos».`);
}
return out;
